CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'staff' CHECK(role IN('admin','staff')),active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS projects(id SERIAL PRIMARY KEY,name TEXT NOT NULL,client_name TEXT,location TEXT,status TEXT DEFAULT 'Planning',progress NUMERIC DEFAULT 0,start_date DATE,end_date DATE,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS budgets(id SERIAL PRIMARY KEY,project_id INTEGER REFERENCES projects(id) ON DELETE CASCADE,category TEXT NOT NULL,budget_amount NUMERIC(14,2) DEFAULT 0,actual_amount NUMERIC(14,2) DEFAULT 0,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS attendance(id SERIAL PRIMARY KEY,project_id INTEGER REFERENCES projects(id) ON DELETE CASCADE,worker_name TEXT NOT NULL,attendance_date DATE DEFAULT CURRENT_DATE,status TEXT DEFAULT 'Present',check_in TIME,check_out TIME,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS materials(id SERIAL PRIMARY KEY,project_id INTEGER REFERENCES projects(id) ON DELETE CASCADE,name TEXT NOT NULL,unit TEXT,quantity_received NUMERIC DEFAULT 0,quantity_used NUMERIC DEFAULT 0,reorder_level NUMERIC DEFAULT 0,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS progress_photos(id SERIAL PRIMARY KEY,project_id INTEGER REFERENCES projects(id) ON DELETE CASCADE,photo_url TEXT NOT NULL,caption TEXT,taken_at TIMESTAMPTZ DEFAULT now(),created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS client_reports(id SERIAL PRIMARY KEY,project_id INTEGER REFERENCES projects(id) ON DELETE CASCADE,title TEXT NOT NULL,summary TEXT,report_date DATE DEFAULT CURRENT_DATE,created_at TIMESTAMPTZ DEFAULT now());
